!function(n){var t=function(n,t){t(".pxl-countdown").each(function(){var n=t(this),o=t(this).find("> div").data("count-down");setInterval(function(){var t=(new Date).getTime(),d=new Date(o).getTime()-t,a=Math.floor(d/864e5),i=Math.floor(d%864e5/36e5),e=Math.floor(d%36e5/6e4),s=Math.floor(d%6e4/1e3),c=1!==a?n.attr("data-days"):n.attr("data-day"),r=1!==i?n.attr("data-hours"):n.attr("data-hour"),u=1!==e?n.attr("data-minutes"):n.attr("data-minute"),v=1!==s?n.attr("data-seconds"):n.attr("data-second");i=i<10?"0"+i:i,e=e<10?"0"+e:e,s=s<10?"0"+s:s;for(var l=[],w=(a=a<10?"0"+a:a).toString(),m=0;m<w.length;m++)l.push("<span>"+w[m]+"</span>");var h=[],f=i.toString();for(m=0;m<f.length;m++)h.push("<span>"+f[m]+"</span>");var p=[],g=e.toString();for(m=0;m<g.length;m++)p.push("<span>"+g[m]+"</span>");var y=[],j=s.toString();for(m=0;m<j.length;m++)y.push("<span>"+j[m]+"</span>");n.html('<div class="countdown-item countdown-day"><div class="countdown-item-inner"><div class="countdown-amount">'+l.join()+' </div><div class="countdown-period">'+c+'</div></div></div><div class="countdown-item countdown-hour"><div class="countdown-item-inner"><div class="countdown-amount">'+h.join()+'</div><div class="countdown-period">'+r+'</div></div></div><div class="countdown-item countdown-minute"><div class="countdown-item-inner"><div class="countdown-amount">'+p.join()+'</div><div class="countdown-period">'+u+'</div></div></div><div class="countdown-item countdown-second"><div class="countdown-item-inner"><div class="countdown-amount">'+y.join()+'</div><div class="countdown-period">'+v+"</div></div></div>")},100)})};n(window).on("elementor/frontend/init",function(){elementorFrontend.hooks.addAction("frontend/element_ready/pxl_countdown.default",t),elementorFrontend.hooks.addAction("frontend/element_ready/pxl_event_countdown.default",t)})}(jQuery);
